current_weapon = {"name": "m4a1", "pattern": m4a1}

def do_control(ser, stop_event):
    for ammo in current_weapon["pattern"]:
        if stop_event.is_set():
            break
        try:
            ser.write(f"{int(3.205*ammo['x'])},{int(3.205*ammo['y'])}\n".encode())
            ser.flush()
        except serial.SerialTimeoutException:
            print("Write timeout occurred during control, skipping...")
            continue
        time.sleep(0.001 * ammo["d"]-0.0015)

def lets_cheat():
    config_path = os.path.join(os.path.dirname(__file__), 'configs.json')
    with open(config_path, 'r') as f:
        config = json.load(f)

    serial_config = config['serial']
    ser = serial.Serial(serial_config['port'], 115200)
    aim_config = config['auto_aim']
    aim_active = False
    stop_event = threading.Event()
    control_thread = None

    def on_aim_press(event):
        nonlocal aim_active, control_thread
        if event.name == aim_config["hotkey"]:
            if not aim_active:
                aim_active = True
                stop_event.clear()
                print("do auto_control")
                control_thread = threading.Thread(target=do_control, args=(ser, stop_event))
                control_thread.start()

    def on_aim_release(event):
        nonlocal aim_active
        if event.name == aim_config["hotkey"]:
            print("off auto_control")
            stop_event.set()  # 停止控制线程
            try:
                ser.write(b"9999,9999\n")
                ser.flush()
            except serial.SerialTimeoutException:
                print("Write timeout occurred when stopping control.")
            aim_active = False
            
    def on_weapon_switch(e):
        if current_weapon["name"] == "m4a1":
            current_weapon["name"] = "ak47"
            current_weapon["pattern"] = ak47
        else:
            current_weapon["name"] = "m4a1"
            current_weapon["pattern"] = m4a1
        print(f"Switched to {current_weapon['name']}")

    keyboard.on_press_key(aim_config["hotkey"], on_aim_press)
    keyboard.on_release_key(aim_config["hotkey"], on_aim_release)
    keyboard.on_press_key(']', on_weapon_switch)
    keyboard.wait()

lets_cheat()
